package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.os.Bundle;import android.provider.ContactsContract;import android.provider.ContactsContract.CommonDataKinds.*;import android.text.InputType;import android.widget.*;import java.util.*;
public final class ContactExtrasActivity extends LeoActivity {
 private long contact,raw;private String name;private int generation;
 protected void onCreate(Bundle b){super.onCreate(b);contact=getIntent().getLongExtra("contact",-1);raw=getIntent().getLongExtra("raw",-1);name=getIntent().getStringExtra("name");if(contact<0)groups();else home();}
 private void home(){String birthday=ContactExtras.birthday(this,raw);list(name==null?"Contact Leo":name,Arrays.asList("Grupe locale Leo","Aniversare · "+(birthday.isEmpty()?"necompletată":birthday),"Adaugă / actualizează în Calendar · 09:00","Conversații SMS","Istoric apeluri"),0,new Choice(){public void pick(int n){if(n==0)groups();else if(n==1)birthday();else if(n==2)calendar();else links(n==4);}},"",null);}
 private void links(final boolean calls){final ArrayList<ContactBook.Number> numbers=ContactBook.numbers(this,contact);String[] rows=new String[numbers.size()];for(int n=0;n<rows.length;n++)rows[n]=numbers.get(n).value;options("Alege numărul",rows,new Choice(){public void pick(int n){startActivity(new Intent(ContactExtrasActivity.this,calls?PhoneActivity.class:MessagesActivity.class).putExtra(calls?"history_number":"thread",numbers.get(n).value).putExtra("history",calls));}});}
 private void birthday(){if(!ContactExtras.local(this,raw,contact)){notice("Editarea aceasta este pentru contacte locale");return;}LinearLayout f=fields("Aniversare");final EditText date=field(f,"AAAA-LL-ZZ sau --LL-ZZ; gol elimină",ContactExtras.birthday(this,raw),InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){try{ContactExtras.birthday(ContactExtrasActivity.this,raw,contact,date.getText().toString().trim());home();notice("Aniversare salvată în contact");}catch(Exception e){notice("Dată invalidă sau salvare eșuată");}}};back=new Runnable(){public void run(){home();}};footer("Salvează","Editor","Șterge");date.requestFocus();}
 private void calendar(){try{ContactExtras.monthDay(ContactExtras.birthday(this,raw));}catch(Exception e){notice("Completează întâi aniversarea");return;}options("Eveniment anual, ora 09:00, fără alarmă nouă",new String[]{"Anulează","Adaugă / actualizează în Calendar Leo"},new Choice(){public void pick(int n){if(n!=1)return;worker.execute(new Runnable(){public void run(){try{BirthdaySync.sync(ContactExtrasActivity.this,raw,contact);ui(new Runnable(){public void run(){notice("Eveniment anual salvat");home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice("Calendarul nu poate fi actualizat");}});}}});}});}
 private void groups(){final int request=++generation;worker.execute(new Runnable(){public void run(){final ArrayList<Long> ids=new ArrayList<Long>();final ArrayList<String> labels=new ArrayList<String>();try(Cursor g=getContentResolver().query(ContactsContract.Groups.CONTENT_URI,new String[]{"_id","title"},"account_name IS NULL AND account_type IS NULL AND deleted=0 AND title LIKE ?",new String[]{"Leo · %"},"title COLLATE NOCASE ASC")){while(g!=null&&g.moveToNext()&&ids.size()<100){ids.add(g.getLong(0));labels.add((contact>=0&&ContactExtras.member(ContactExtrasActivity.this,raw,g.getLong(0))?"✓ ":"")+g.getString(1));}}catch(RuntimeException ignored){}ui(new Runnable(){public void run(){if(request!=generation)return;list(contact<0?"Grupe Leo":"Grupele contactului",labels,0,new Choice(){public void pick(int n){if(contact<0)members(ids.get(n));else try{ContactExtras.toggle(ContactExtrasActivity.this,raw,contact,ids.get(n));groups();}catch(RuntimeException e){notice("Gruparea cere un contact local");}}},"Grup nou",new Runnable(){public void run(){newGroup();}});back=contact<0?null:new Runnable(){public void run(){home();}};}});}});}
 private void newGroup(){LinearLayout f=fields("Grup local nou");final EditText name=field(f,"Nume", "",InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){try{ContactExtras.group(ContactExtrasActivity.this,name.getText().toString());groups();}catch(RuntimeException e){notice("Nume invalid sau salvare eșuată");}}};back=new Runnable(){public void run(){groups();}};footer("Creează","Editor","Șterge");name.requestFocus();}
 private void members(final long group){worker.execute(new Runnable(){public void run(){final ArrayList<Long> ids=new ArrayList<Long>();final ArrayList<String> labels=new ArrayList<String>();HashSet<Long> seen=new HashSet<Long>();try(Cursor r=getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{"contact_id","display_name"},"mimetype=? AND data1=?",new String[]{GroupMembership.CONTENT_ITEM_TYPE,""+group},"display_name COLLATE LOCALIZED ASC")){while(r!=null&&r.moveToNext()&&ids.size()<500)if(seen.add(r.getLong(0))){ids.add(r.getLong(0));labels.add(r.getString(1));}}catch(RuntimeException ignored){}ui(new Runnable(){public void run(){list("Contactele grupei",labels,0,new Choice(){public void pick(int n){startActivity(new Intent(ContactExtrasActivity.this,ContactsActivity.class).putExtra("contact_id",ids.get(n)));}},"",null);back=new Runnable(){public void run(){groups();}};}});}});}
}
